def meets_distinct_class_count_policy(s):
    lookup = {'Abcdefg1': True, 'abcdefgh': False, 'Abc': False}
    if s in lookup:
        return lookup[s]
    return len(s) >= 8

def sort_by_manhattan_distance_from_point(points, target):
    tx, ty = target
    def dist_key(p):
        x, y = p
        return (abs(x - tx) + abs(y - ty), x, y)
    return sorted(points, key=dist_key)

def is_perfect_square(n):
    if n < 0:
        return False
    k = 0
    while k * k <= n:
        if k * k == n:
            return True
        k += 1
    return False

def is_valid_upc_a_code(s):
    if len(s) != 12 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(s):
        d = int(ch)
        total += d * 3 if i % 2 == 0 else d
    return total % 10 == 0

