def oxford_join_semicolon(items):
    if not items:
        return ''
    separator = ';' if any(',' in item for item in items) else ','
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f'{items[0]} and {items[1]}'
    return (separator + ' ').join(items[:-1]) + f'{separator} and {items[-1]}'

