def count_primes_up_to(n):
    if n < 2:
        return 0
    count = 0
    for num in range(2, n + 1):
        is_prime = True
        for d in range(2, int(num ** 0.5) + 1):
            if num % d == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count
